using System.Collections.Generic;
using UnityEngine;
public class PoisonField : MonoBehaviour
{
	private static GameObject prefab;
	private Entity parentEntity;
	private float atkRadius;
	private float atkChance = 0.075f;
	private Vector2 atkPosition;
	private ChaosQuickStopwatch atkStopwatch = new ChaosQuickStopwatch(0.25f);
	private List<GameObject> targetList = new List<GameObject>();
	private string atkCategory;
	private string atkID;
	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/AreaEffects/PoisonField.prefab"));
	private void Awake()
	{
		atkRadius = transform.Find("Sprite").GetComponent<SpriteRenderer>().sprite.bounds.max.x;
		atkRadius *= transform.localScale.x;
		if (atkRadius < 0f)
		{
			atkRadius *= -1f;
		}
	}
	private void Update()
	{
		if (atkStopwatch.IsRunning || parentEntity == null || parentEntity.fsm.currentStateName.Contains("Dead") || parentEntity.fsm.currentStateName.Contains("Paused"))
		{
			return;
		}
		atkStopwatch.IsRunning = true;
		if (!(Random.value > atkChance))
		{
			targetList = Entity.GetAllTargetsInRange(GameController.enemies, transform.position, atkRadius);
			if (targetList.Count != 0)
			{
				atkPosition = targetList[Random.Range(0, targetList.Count)].transform.position;
				PoolManager.GetPoolItem<AttackGeneric>().CircleAttack(atkPosition, atkCategory, atkID);
				targetList.Clear();
			}
		}
	}
	public void Initialize(Entity givenEnt, string givenCat, string givenID)
	{
		parentEntity = givenEnt;
		atkCategory = givenCat;
		atkID = givenID;
	}
}
